/* ---------- nutrition maths ---------- */
function latestWeightEntry(){const ds=Object.keys(S.days).filter(d=>S.days[d].weight>0).sort();return ds.length?{date:ds[ds.length-1],kg:S.days[ds[ds.length-1]].weight}:null}
function latestWeight(){const e=latestWeightEntry();return e?e.kg:S.profile.startWeight}
function plan(){
  const P=S.profile,w=latestWeight();
  const bmr=P.sex==='m'?10*w+6.25*P.height-5*P.age+5:10*w+6.25*P.height-5*P.age-161;
  const base=bmr*P.activity;
  const fbDaily=P.fbPerWeek*(P.fbMinutes/60)*7.5*w/7;
  const gymDaily=(P.gymPerWeek||0)*((P.gymMinutes||0)/60)*5*w/7;
  const sportDaily=fbDaily+gymDaily;
  const weeksLeft=Math.max(0.5,(parseYmd(P.goalDate)-new Date())/(7*864e5));
  const toLose=w-P.goalWeight;
  const needRate=toLose/weeksLeft;
  const safeMax=Math.round(clamp(w*0.01,0.5,1.0)*20)/20;
  const rate=P.rate??Math.max(0.25,Math.min(needRate,safeMax));
  const deficit=rate*7700/7;
  const floor=P.sex==='m'?1500:1200;
  const kcalRest=Math.max(floor,r0(base-deficit));
  const avgIntake=kcalRest+sportDaily*P.eatBack/100;
  const avgBurn=base+sportDaily;
  const rateAt=eb=>Math.max(0.05,(avgBurn-(kcalRest+sportDaily*eb/100))*7/7700);
  const atDateFor=eb=>Math.max(P.goalWeight,w-rateAt(eb)*weeksLeft);
  const effRate=Math.max(0.05,(avgBurn-avgIntake)*7/7700);
  const weeksToGoal=toLose>0?toLose/effRate:0;
  const goalEta=new Date(Date.now()+weeksToGoal*7*864e5);
  const atGoalDate=Math.max(P.goalWeight,w-effRate*weeksLeft);
  const protein=r0(P.proteinPerKg*w),fat=r0(P.fatPerKg*w);
  return{w,bmr,base,fbDaily,gymDaily,sportDaily,atDateFor,weeksLeft,toLose,needRate,safeMax,rate,deficit,kcalRest,effRate,goalEta,atGoalDate,protein,fat,fiber:P.fiber,floor,avgBurn,floored:base-deficit<floor};
}
function targetsFor(d){const pl=plan();const ex=day(d).ex.filter(e=>e.id!=='sauna').reduce((a,e)=>a+e.kcal,0);const kcal=r0(pl.kcalRest+ex*S.profile.eatBack/100);const c=Math.max(50,r0((kcal-pl.protein*4-pl.fat*9)/4));return{kcal,p:pl.protein,c,f:pl.fat,fib:pl.fiber,ex}}
function totals(d){const t={kcal:0,p:0,c:0,f:0,fib:0,sug:0};for(const it of day(d).foods){const g=it.grams/100;for(const k in t)t[k]+=(it.per100[k]||0)*g}return t}
function fitScore(n){
  if(!n||!(n.kcal>0))return null;
  const pDen=(n.p||0)/n.kcal*100,fibDen=(n.fib||0)/n.kcal*100,fatPct=(n.f||0)*9/n.kcal,sug=n.sug||0;
  const s=clamp(pDen/10,0,1)*45+clamp(fibDen/3,0,1)*20+clamp((0.45-fatPct)/0.25,0,1)*20+clamp((20-sug)/15,0,1)*15;
  return r0(s);
}
function scoreMeta(s){if(s==null)return{label:'No data',color:'var(--ink2)'};if(s>=75)return{label:'Great fit',color:'var(--good)'};if(s>=55)return{label:'Good',color:'var(--ok)'};if(s>=35)return{label:'In moderation',color:'var(--warn)'};return{label:'Doesn’t fit the plan',color:'var(--bad)'}}
function reasons(n){
  const out=[];if(!n||!(n.kcal>0))return out;
  const pDen=(n.p||0)/n.kcal*100,fibDen=(n.fib||0)/n.kcal*100,fatPct=(n.f||0)*9/n.kcal,sug=n.sug||0;
  out.push(pDen>=8?['good',`High protein: ${r1(pDen)} g per 100 kcal`]:pDen>=4?['warn',`Moderate protein: ${r1(pDen)} g per 100 kcal`]:['bad',`Low protein: ${r1(pDen)} g per 100 kcal`]);
  if(n.fib==null)out.push(['warn','Fibre not listed']);else out.push(fibDen>=2.5?['good',`Good fibre: ${r1(n.fib)} g per 100 g`]:n.fib>=3?['warn',`Some fibre: ${r1(n.fib)} g per 100 g`]:['bad',`Little fibre: ${r1(n.fib)} g per 100 g`]);
  out.push(fatPct<=0.25?['good',`Low fat: ${r0(fatPct*100)}% of calories`]:fatPct<=0.4?['warn',`Medium fat: ${r0(fatPct*100)}% of calories`]:['bad',`High fat: ${r0(fatPct*100)}% of calories`]);
  out.push(sug<=5?['good',`Low sugar: ${r1(sug)} g per 100 g`]:sug<=12?['warn',`Some sugar: ${r1(sug)} g per 100 g`]:['bad',`High sugar: ${r1(sug)} g per 100 g`]);
  return out;
}
const RC={good:'var(--good)',warn:'var(--warn)',bad:'var(--bad)'};

