/* search */
let qT,lastQ='';$('#q').oninput=()=>{clearTimeout(qT);const v=$('#q').value.trim();qT=setTimeout(()=>{if(v.length>=3||!v)doSearch(v)},900)};
$('#qgo').onclick=()=>doSearch($('#q').value.trim());
$('#q').onkeydown=e=>{if(e.key==='Enter')doSearch($('#q').value.trim())};
let qSeq=0;
async function doSearch(q){
  const seq=++qSeq,el=$('#results'),st=$('#qstatus');
  const ql=q.toLowerCase();
  const tokens=ql.split(/\s+/).filter(w=>w.length>=2);
  let aliasHits=[];try{aliasHits=ql?findFoods(correctTypos(ql)).map(f=>f.st):[]}catch(e){}
  const score=p=>{if(!ql)return 1;const hay=(p.name+' '+(p.src==='staple'?enName(p):'')+' '+(p.brand||'')).toLowerCase();let sc=0;for(const w of tokens){if(hay.includes(w))sc+=2}if(aliasHits.includes(p))sc+=5;return sc};
  const local=[...Object.values(S.custom),...STAPLES].map(p=>({p,sc:score(p)})).filter(x=>x.sc>0).sort((a,b)=>b.sc-a.sc).map(x=>x.p);
  if(!q){st.textContent='Common Dutch staples. Type to search Open Food Facts for branded products.';listProducts(el,local.slice(0,40),'');return}
  listProducts(el,local,'');st.textContent='Searching Open Food Facts…';
  try{
    if(q===lastQ&&searchCache[q]){/* same query, reuse */}
    const off=await offSearch(q,24);
    if(seq!==qSeq)return;
    off.sort((a,b)=>(fitScore(b.per100)??-1)-(fitScore(a.per100)??-1));
    listProducts(el,[...local,...off],'No matches. Try a shorter word, or add it manually.');
    st.textContent=`${local.length} staple${local.length===1?'':'s'} · ${off.length} products from Open Food Facts, best fit first`;
  }catch(e){if(seq!==qSeq)return;st.textContent=(local.length?'Built-in foods shown. ':'No built-in match. ')+'Open Food Facts search is busy right now; try again in a minute, say it with the mic, or scan the barcode.'}
}
const searchCache={};
async function offSearch(q,n){
  if(searchCache[q])return searchCache[q];
  const F='code,product_name,product_name_nl,product_name_en,brands,quantity,serving_quantity,nutriscore_grade,nutriments,image_front_small_url';
  const urls=[`https://nl.openfoodfacts.org/cgi/search.pl?search_terms=${encodeURIComponent(q)}&search_simple=1&action=process&json=1&page_size=${n}&fields=${F}`,`https://world.openfoodfacts.org/cgi/search.pl?search_terms=${encodeURIComponent(q)}&search_simple=1&action=process&json=1&page_size=${n}&fields=${F}&countries_tags_en=netherlands`,`https://search.openfoodfacts.org/search?q=${encodeURIComponent(q)}&langs=nl,en&page_size=${n}&fields=${F}`];
  let lastErr=null;
  for(const u of urls){try{const r=await fetch(u);if(!r.ok)throw new Error('HTTP '+r.status);const j=await r.json();const list=(j.products||j.hits||[]).map(mapOFF).filter(Boolean);if(list.length||u===urls[urls.length-1]){searchCache[q]=list;return list}}catch(e){lastErr=e}}
  throw lastErr||new Error('search failed');
}
function mapOFF(p){
  const n=p.nutriments||{};let kcal=n['energy-kcal_100g'];if(kcal==null&&n['energy_100g']!=null)kcal=n['energy_100g']/4.184;
  if(!(kcal>0)&&!(n.proteins_100g>=0))return null;
  const num=v=>v==null||v===''?null:+v;
  return{name:p.product_name_nl||p.product_name||p.product_name_en||'Unnamed product',brand:(p.brands||'').split(',')[0].trim(),barcode:p.code,qty:p.quantity,serving:num(p.serving_quantity),nutri:(p.nutriscore_grade||'').toLowerCase(),img:p.image_front_small_url||null,src:'off',
    per100:{kcal:r1(kcal||0),p:num(n.proteins_100g)??0,c:num(n.carbohydrates_100g)??0,f:num(n.fat_100g)??0,fib:num(n.fiber_100g),sug:num(n.sugars_100g),sat:num(n['saturated-fat_100g'])}};
}
/* barcode lookup */
async function lookup(code){
  code=String(code).replace(/\D/g,'');if(!code){toast('No barcode');return}
  const st=$('#scanstatus');st.textContent='Looking up '+code+'…';
  const own=Object.values(S.custom).find(p=>p.barcode===code)||S.favs.find(p=>p.barcode===code)||S.recent.find(p=>p.barcode===code);
  if(own){st.textContent='';showProduct(own);return}
  try{
    const r=await fetch(`https://nl.openfoodfacts.org/api/v2/product/${code}.json?fields=code,product_name,product_name_nl,product_name_en,brands,quantity,serving_quantity,nutriscore_grade,nutriments,image_front_small_url`);
    const j=await r.json();
    if(j.status===1&&j.product){const p=mapOFF(j.product);if(p){st.textContent='';showProduct(p);return}}
    st.textContent='Not in Open Food Facts yet.';notFound(code);
  }catch(e){st.textContent='Lookup failed (offline, or this preview blocks the request). You can add the product manually.';notFound(code)}
}
function notFound(code){
  openSheet(`<h2>Product not found</h2><p class="small muted" style="margin:0">Barcode <b class="tnum">${esc(code)}</b> isn't in Open Food Facts (or the request was blocked). Type the label values once and it's saved for this barcode.</p><div class="row"><button class="btn primary wide" id="nf-manual">Enter from label</button><button class="btn ghost" id="nf-close">Close</button></div>`);
  $('#nf-manual').onclick=()=>{closeSheet();pane='manual';renderAdd();$('#m-code').value=code;$('#m-name').focus()};
  $('#nf-close').onclick=closeSheet;
}
$('#codego').onclick=()=>lookup($('#codeinput').value);
$('#codeinput').onkeydown=e=>{if(e.key==='Enter')lookup($('#codeinput').value)};
/* manual */
$('#m-go').onclick=()=>{
  const v=id=>{const x=parseFloat($(id).value);return isNaN(x)?null:x};
  const name=$('#m-name').value.trim();if(!name){toast('Give it a name');return}
  const kcal=v('#m-kcal');if(!(kcal>=0)){toast('kcal per 100 g is required');return}
  const p={name,brand:$('#m-brand').value.trim(),barcode:$('#m-code').value.replace(/\D/g,'')||null,src:'custom',per100:{kcal,p:v('#m-p')??0,c:v('#m-c')??0,f:v('#m-f')??0,fib:v('#m-fib'),sug:v('#m-sug')}};
  S.custom[p.barcode||('c_'+name.toLowerCase())]=p;save();
  ['#m-name','#m-brand','#m-kcal','#m-p','#m-c','#m-f','#m-fib','#m-sug','#m-code'].forEach(i=>$(i).value='');
  showProduct(p);
};

