/* ---------- Google Calendar links (no login needed: opens the Calendar app you're already signed into) ---------- */
const enc=encodeURIComponent;
function gcalUrl(o){
  const dd=o.date.replace(/-/g,'');let dates;
  if(o.time){const [h,m]=o.time.split(':').map(Number);const st=parseYmd(o.date);st.setHours(h,m,0,0);const en=new Date(st.getTime()+(o.dur||15)*60000);const f=x=>ymd(x).replace(/-/g,'')+'T'+z(x.getHours())+z(x.getMinutes())+'00';dates=f(st)+'/'+f(en)}
  else dates=dd+'/'+addDays(o.date,1).replace(/-/g,'');
  let u=`https://calendar.google.com/calendar/render?action=TEMPLATE&text=${enc(o.title)}&dates=${dates}&details=${enc(o.details||'')}&ctz=Europe/Amsterdam`;
  if(o.daily)u+='&recur='+enc('RRULE:FREQ=DAILY');return u;
}
function gcalFoodUrl(d){
  const t=totals(d),T=targetsFor(d),D=day(d);
  let det=`Pitch & Plate · ${fmt(t.kcal)} / ${fmt(T.kcal)} kcal · protein ${r0(t.p)} g · fibre ${r0(t.fib)} g · carbs ${r0(t.c)} g · fat ${r0(t.f)} g\n`;
  for(const m of MEALS){const items=D.foods.filter(f=>f.meal===m);if(!items.length)continue;det+=`\n${m}:\n`+items.map(f=>`• ${f.name} ${f.grams} g (${fmt(f.per100.kcal*f.grams/100)} kcal)`).join('\n')+'\n'}
  if(D.ex.length)det+=`\nTraining:\n`+D.ex.map(e=>`• ${e.name} ${e.min} min${e.id==='sauna'?'':` (${fmt(e.kcal)} kcal)`}`).join('\n')+'\n';
  if(D.weight)det+=`\nWeight: ${D.weight} kg`;
  if(det.length>1600)det=det.slice(0,1590)+'…';
  return gcalUrl({title:`Food log · ${fmt(t.kcal)} kcal · P ${r0(t.p)} g`,details:det,date:d});
}

