let sampleFn=null,sampleChecked=false;
async function getSample(){if(!sampleChecked){sampleChecked=true;try{if(window.claude&&typeof window.claude.use==='function')sampleFn=await window.claude.use('sample')}catch(e){sampleFn=null}}return sampleFn}
function coachMode(){if(sampleFn)return 'page';if(S.settings.apiKey)return 'api';return 'rules'}
async function askClaudeAPI(key,system,messages){
  const body={model:'claude-opus-5',max_tokens:1024,system,messages,output_config:{effort:'low'}};
  const headers={'content-type':'application/json','x-api-key':key,'anthropic-version':'2023-06-01','anthropic-dangerous-direct-browser-access':'true'};
  let r=await fetch('https://api.anthropic.com/v1/messages',{method:'POST',headers:{...headers,'anthropic-beta':'server-side-fallback-2026-07-01'},body:JSON.stringify({...body,fallbacks:'default'})});
  if(r.status===400){r=await fetch('https://api.anthropic.com/v1/messages',{method:'POST',headers,body:JSON.stringify(body)})}
  const j=await r.json().catch(()=>({}));
  if(!r.ok)throw new Error((j.error&&j.error.message)||('HTTP '+r.status));
  if(j.stop_reason==='refusal')return "I can't help with that one. Ask me about the food.";
  return (j.content||[]).filter(b=>b.type==='text').map(b=>b.text).join('\n').trim()||'(empty answer)';
}
async function askCoach(history){
  const sys=COACH_SYSTEM+'\n\n'+coachContext();
  const sm=await getSample();
  if(sm){const turns=history.map((m,i)=>({role:m.role,content:i===0?sys+'\n\nIVAN SAYS: '+m.content:m.content}));const r=await sm(turns,{modelTier:'default',cache:false});return r.text}
  if(S.settings.apiKey)return askClaudeAPI(S.settings.apiKey,sys,history.map(m=>({role:m.role,content:m.content})));
  return ruleCoach(history[history.length-1].content);
}
function ruleCoach(q){
  const T=targetsFor(cur),t=totals(cur);const left=T.kcal-t.kcal,pLeft=T.p-t.p,cLeft=T.c-t.c;
  const ql=q.toLowerCase();
  const words=ql.split(/[,;\/\n+]|\band\b|\ben\b|\bwith\b|\bmet\b|\bor\b|\bof\b/).map(w=>w.replace(/[^a-zà-ü ]/g,'').trim()).filter(Boolean);
  const found=[],unknown=[];
  const STOP=new Set('i ive have has had got there is are at work home lunch dinner breakfast snack what should could can do eat eating the a an some my me now today tonight for from left over please hi hey coach ik heb wat moet kan eten er zijn vandaag nu op het de een mijn'.split(' '));
  for(let w of words){
    const stripped=w.split(' ').filter(x=>!STOP.has(x)).join(' ').trim();
    if(!stripped)continue;
    const key=Object.keys(ALIAS).sort((a,b)=>b.length-a.length).find(k=>w.includes(k));
    if(!key)w=stripped;
    const name=key?ALIAS[key]:null;
    const st=name?STAPLES.find(x=>x.name.toLowerCase().includes(name.toLowerCase())):STAPLES.find(x=>w.length>3&&x.name.toLowerCase().includes(w));
    if(st){if(!found.some(f=>f.st===st))found.push({w,st,score:fitScore(st.per100)||0})}
    else if(w.length>2&&w.split(' ').length<=2)unknown.push(w);
  }
  const out=[];
  if(left<150){
    out.push(left<0?`You're ${fmt(-left)} kcal over today. Stop eating.`:`${fmt(left)} kcal left. That's not a meal, that's a glass of milk.`);
    if(pLeft>15)out.push(`Protein is still ${r0(pLeft)} g short: 150 g magere kwark (72 kcal, 13 g protein), then you're done.`);
    else if(cLeft>20&&left>60)out.push(`If you must: a small banana (~80 kcal) or a cucumber. Then water.`);
    else out.push(`Water, tea, sparkling water or black coffee. If it's late, go to bed. Tomorrow is a new day.`);
    return out.join('\n');
  }
  if(!found.length){
