  const take=(f,g)=>{const n=f.st.per100;pick.push(`${g} g ${short(f.st)} (${fmt(n.kcal*g/100)} kcal, ${r0(n.p*g/100)} g protein)`);kcal+=n.kcal*g/100;prot+=n.p*g/100};
