let stream=null,scanTimer=null,zx=null,scanning=false;
$('#scanstart').onclick=startScan;$('#scanstop').onclick=stopScan;
async function startScan(){
  const st=$('#scanstatus');
  if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){st.textContent='Camera not available here. Open the installed app over https, or type the barcode below.';return}
  try{
    scanning=true;$('#scanstart').hidden=true;$('#scanstop').hidden=false;$('#scanidle').hidden=true;$('#video').hidden=false;$('#frame').hidden=false;
    const video=$('#video');
    if('BarcodeDetector' in window){
      let formats=['ean_13','ean_8','upc_a','upc_e','code_128'];
      try{const sup=await window.BarcodeDetector.getSupportedFormats();formats=formats.filter(f=>sup.includes(f))}catch(e){}
      if(formats.length){
        stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});
        video.srcObject=stream;await video.play();
        const det=new window.BarcodeDetector({formats});st.textContent='Scanning…';
        let fails=0;scanTimer=setInterval(async()=>{if(video.readyState<2||!scanning)return;try{const codes=await det.detect(video);if(codes.length){onCode(codes[0].rawValue)}}catch(e){if(++fails>8){clearInterval(scanTimer);scanTimer=null;st.textContent='Switching scanner…';startZxing(video,st).catch(err=>{st.textContent='Scanner failed: '+(err&&err.message||err);stopScan()})}}},220);
        return;
      }
    }
    await startZxing(video,st);
  }catch(e){st.textContent=e&&e.name==='NotAllowedError'?'Camera permission denied. Allow camera access for this site in Chrome, or type the barcode.':'Could not start the camera: '+(e&&e.message||e);stopScan()}
}
async function startZxing(video,st){
  st.textContent='Loading scanner…';
  if(!window.ZXing){await new Promise((res,rej)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/@zxing/library@0.21.3/umd/index.min.js';s.onload=res;s.onerror=()=>rej(new Error('Scanner library could not load. Check your connection and try again.'));document.head.appendChild(s)})}
  if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}
  zx=new window.ZXing.BrowserMultiFormatReader();st.textContent='Scanning…';
  await zx.decodeFromConstraints({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}}},video,(result)=>{if(result&&scanning)onCode(result.getText())});
}
function onCode(code){if(!scanning)return;stopScan();try{navigator.vibrate&&navigator.vibrate(40)}catch(e){}$('#codeinput').value=code;lookup(code)}
function stopScan(){
  scanning=false;clearInterval(scanTimer);scanTimer=null;
  if(zx){try{zx.reset()}catch(e){}zx=null}
  if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}
  const v=$('#video');if(v){v.srcObject=null;v.hidden=true}
  $('#frame').hidden=true;$('#scanidle').hidden=false;$('#scanstart').hidden=false;$('#scanstop').hidden=true;
}
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopScan()});

